import type { Directory, User } from "./types.ts";

export function grantsFor(user: User, directory: Directory): Set<string> {
  // Roles inherit grants through parent links (e.g. auditor -> report-reader), so walk each chain.
  const grants = new Set<string>();
  const seen = new Set<string>();
  for (const assigned of user.roles) {
    let name: string | undefined = assigned;
    while (name !== undefined && !seen.has(name)) {
      seen.add(name);
      const role = directory[name];
      if (!role) break;
      for (const grant of role.grants) grants.add(grant);
      name = role.parent;
    }
  }
  return grants;
}
EOF
